import re

results = []

def rich_text(text):
    parts = re.split(r'(\*\*.*?\*\*)', text)
    output = []

    for part in parts:
        if not part:
            continue

        bold = part.startswith("**") and part.endswith("**")
        clean = part[2:-2] if bold else part

        # Notion text objects must stay below 2000 characters
        while clean:
            piece = clean[:1900]
            if len(clean) > 1900:
                boundary = max(piece.rfind(" "), piece.rfind("\n"))
                if boundary > 0:
                    piece = clean[:boundary + 1]

            output.append({
                "type": "text",
                "text": {"content": piece},
                "annotations": {"bold": bold}
            })
            clean = clean[len(piece):]

    return output

for item in _items:
    data = item["json"]
    report = data["output"][0]["content"][0]["text"]

    if not report or not report.strip():
        raise ValueError("The interview report is empty.")

    blocks = []
    paragraph_lines = []

    def add_block(kind, content):
        if not content.strip():
            return
        blocks.append({
            "object": "block",
            "type": kind,
            kind: {"rich_text": rich_text(content)}
        })

    def flush_paragraph():
        if paragraph_lines:
            add_block("paragraph", " ".join(paragraph_lines))
            paragraph_lines.clear()

    for raw_line in report.splitlines():
        line = raw_line.strip()

        if not line:
            flush_paragraph()
            continue

        heading = re.match(r'^(#{1,3})\s+(.+)$', line)
        bullet = re.match(r'^[-*]\s+(.+)$', line)
        numbered = re.match(r'^\d+[.)]\s+(.+)$', line)

        if heading:
            flush_paragraph()
            level = len(heading.group(1))
            add_block("heading_" + str(level), heading.group(2))

        elif bullet:
            flush_paragraph()
            add_block("bulleted_list_item", bullet.group(1))

        elif numbered:
            flush_paragraph()
            add_block("numbered_list_item", numbered.group(1))

        else:
            paragraph_lines.append(line)

    flush_paragraph()

    results.append({
        "json": {
            "report_text": report,
            "report_length": len(report),
            "total_blocks": len(blocks),
            "notion_blocks": blocks
        }
    })

return results
